package com.kaymlyn.planeteater.celestial;

import com.kaymlyn.planeteater.resources.Composition;
import com.kaymlyn.planeteater.resources.Material;
import com.kaymlyn.planeteater.physics.Vector3D;
import lombok.Getter;

/**
 * Represents an asteroid with minable resources
 * 
 * Generated by Claude (Sonnet 4.5)
 */
@Getter
public class Asteroid extends CelestialBody {
    
    public enum AsteroidType {
        C_TYPE,  // Carbonaceous - rich in water, carbon
        S_TYPE,  // Silicaceous - silicates, some metals
        M_TYPE   // Metallic - iron, nickel rich
    }
    
    private AsteroidType type;
    
    public Asteroid(String id, Vector3D position, Vector3D velocity,
                    Composition composition, AsteroidType type) {
        super(id, position, velocity, composition);
        this.type = type;
    }
    
    /**
     * Create a C-type (carbonaceous) asteroid
     * Rich in volatiles, organic compounds, and hydrated minerals
     */
    public static Asteroid createCType(String id, Vector3D position, Vector3D velocity, double targetRadius) {
        Composition comp = new Composition();
        
        // C-type composition (approximate)
        double totalVolume = (4.0 / 3.0) * Math.PI * Math.pow(targetRadius, 3);
        
        comp.addMaterial(Material.ORGANIC_COMPOUNDS, Material.ORGANIC_COMPOUNDS.massForVolume(totalVolume * 0.20));
        comp.addMaterial(Material.WATER_ICE, Material.WATER_ICE.massForVolume(totalVolume * 0.20));
        comp.addMaterial(Material.CARBON, Material.CARBON.massForVolume(totalVolume * 0.10));
        comp.addMaterial(Material.SILICA, Material.SILICA.massForVolume(totalVolume * 0.25));
        comp.addMaterial(Material.IRON_OXIDE, Material.IRON_OXIDE.massForVolume(totalVolume * 0.10));
        comp.addMaterial(Material.MAGNESIUM_OXIDE, Material.MAGNESIUM_OXIDE.massForVolume(totalVolume * 0.10));
        comp.addMaterial(Material.IRON_SULFIDE, Material.IRON_SULFIDE.massForVolume(totalVolume * 0.05));
        
        return new Asteroid(id, position, velocity, comp, AsteroidType.C_TYPE);
    }
    
    /**
     * Create an S-type (silicaceous) asteroid
     * Silicate minerals with moderate metal content
     */
    public static Asteroid createSType(String id, Vector3D position, Vector3D velocity, double targetRadius) {
        Composition comp = new Composition();
        
        double totalVolume = (4.0 / 3.0) * Math.PI * Math.pow(targetRadius, 3);
        
        comp.addMaterial(Material.OLIVINE, Material.OLIVINE.massForVolume(totalVolume * 0.35));
        comp.addMaterial(Material.PYROXENE, Material.PYROXENE.massForVolume(totalVolume * 0.25));
        comp.addMaterial(Material.IRON, Material.IRON.massForVolume(totalVolume * 0.15));
        comp.addMaterial(Material.FELDSPAR, Material.FELDSPAR.massForVolume(totalVolume * 0.10));
        comp.addMaterial(Material.NICKEL, Material.NICKEL.massForVolume(totalVolume * 0.08));
        comp.addMaterial(Material.IRON_SULFIDE, Material.IRON_SULFIDE.massForVolume(totalVolume * 0.05));
        comp.addMaterial(Material.CHROMIUM, Material.CHROMIUM.massForVolume(totalVolume * 0.02));
        
        return new Asteroid(id, position, velocity, comp, AsteroidType.S_TYPE);
    }
    
    /**
     * Create an M-type (metallic) asteroid
     * Iron-nickel rich, potentially exposed planetary cores
     */
    public static Asteroid createMType(String id, Vector3D position, Vector3D velocity, double targetRadius) {
        Composition comp = new Composition();
        
        double totalVolume = (4.0 / 3.0) * Math.PI * Math.pow(targetRadius, 3);
        
        comp.addMaterial(Material.IRON, Material.IRON.massForVolume(totalVolume * 0.70));
        comp.addMaterial(Material.NICKEL, Material.NICKEL.massForVolume(totalVolume * 0.18));
        comp.addMaterial(Material.IRON_SULFIDE, Material.IRON_SULFIDE.massForVolume(totalVolume * 0.05));
        comp.addMaterial(Material.CHROMIUM, Material.CHROMIUM.massForVolume(totalVolume * 0.03));
        comp.addMaterial(Material.PHOSPHORUS, Material.PHOSPHORUS.massForVolume(totalVolume * 0.02));
        comp.addMaterial(Material.SILICA, Material.SILICA.massForVolume(totalVolume * 0.02));
        
        return new Asteroid(id, position, velocity, comp, AsteroidType.M_TYPE);
    }
    
    /**
     * Mine a specific material from this asteroid
     * Returns the actual amount mined (may be less than requested)
     */
    public double mineMaterial(Material material, double requestedMass) {
        return composition.removeMaterial(material, requestedMass);
    }
    
    /**
     * Check if this asteroid has a specific material available
     */
    public boolean hasMaterial(Material material) {
        return composition.contains(material);
    }
    
    /**
     * Get the amount of a specific material available
     */
    public double getAvailableMaterial(Material material) {
        return composition.getMass(material);
    }
    
    @Override
    public String toString() {
        return String.format("com.kaymlyn.planeteater.entities.system.Asteroid[id=%s, type=%s, pos=%s, mass=%.3e kg, radius=%.1f m]",
            id, type, position, getMass(), getRadius());
    }
}